export async function handoffProgram(runtime, bytes, metadata = {}, options = {}) {
    if (!runtime || typeof runtime.loadMedia !== 'function') {
        throw new TypeError('runtime must expose loadMedia(media)');
    }
    await ensureRuntimeReady(runtime, options);
    const programBytes = normalizeProgramBytes(bytes);
    const name = String(options.fileName || metadata.fileName || metadata.name || `${metadata.artifactId || 'web64-ide'}.prg`);
    const media = Object.freeze({
        name,
        kind: 'program',
        bytes: programBytes,
        autorun: options.autorun !== false,
        metadata: freezeMetadata(metadata)
    });
    const record = await runtime.loadMedia(media);
    return Object.freeze({
        ok: true,
        record,
        media,
        artifactId: metadata.artifactId || null,
        loadAddress: metadata.loadAddress ?? readPrgLoadAddress(programBytes),
        byteLength: programBytes.byteLength,
        autorun: media.autorun
    });
}

